def take(bag, item, limit=3):
    if item in bag or len(bag) >= limit:
        return list(bag)
    return bag + [item]

solution:
def take(bag, item, limit=3):
    if item in bag or len(bag) >= limit:
        return list(bag)
    return bag + [item]

alt:
def take(bag, item, limit=3):
    new = list(bag)
    if item not in new and len(new) < limit:
        new.append(item)
    return new
